from collections import defaultdict, deque

def bfs(adj, start):
    visited = set()
    queue = deque([start])
    order = []
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            order.append(node)
            for neighbor in adj.get(node, []):
                if neighbor not in visited:
                    queue.append(neighbor)
    return order

def dfs(adj, start):
    visited = set()
    order = []
    def _dfs(node):
        if node in visited:
            return
        visited.add(node)
        order.append(node)
        for neighbor in adj.get(node, []):
            _dfs(neighbor)
    _dfs(start)
    return order

def shortest_path(adj, start, end):
    if start == end:
        return [start]
    visited = {start}
    queue = deque([(start, [start])])
    while queue:
        node, path = queue.popleft()
        for neighbor in adj.get(node, []):
            if neighbor == end:
                return path + [neighbor]
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

def has_cycle(adj):
    visited = set()
    rec_stack = set()
    def _has_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                if _has_cycle(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.discard(node)
        return False
    for node in adj:
        if node not in visited:
            if _has_cycle(node):
                return True
    return False
```

