    """Perform a calculation based on operation string."""
    if operation == "add":
        result = a + b
        return result
    elif operation == "subtract":
        result = a - b
        return result
    elif operation == "multiply":
        result = a * b
        return result
    elif operation == "divide":
        if b == 0:
            raise ValueError("Cannot divide by zero")
        result = a / b
        return result
    elif operation == "power":
        result = 1
        for i in range(int(b)):
